    // Hand-built levels must not change when the code is refactored: every entry pins a layout recipe from
    // HandBuiltGoldenLayouts (shapes, links, ceilings) as an exact hash and its geometry as a GeometrySignature
    // compared with a small tolerance. If a change is intentional, regenerate the entries.
    public class HandBuiltGoldenTests
    {
        public readonly struct Golden
        {
            public readonly string Config;
            public readonly int Seed;
            public readonly ulong Layout;
            public readonly GeometrySignature Geometry;

            public Golden(string config, int seed, ulong layout, GeometrySignature geometry)
            {
                Config = config;
                Seed = seed;
                Layout = layout;
                Geometry = geometry;
            }

            public override string ToString() => $"{Config} seed {Seed}";
        }

