        [TestCaseSource(nameof(Levels))]
        public void HandBuiltLevel_IsUnchanged(Golden golden)
        {
            GenerationParameters parameters = HandBuiltGoldenLayouts.CreateParameters(golden.Config);
            LevelLayout layout = HandBuiltGoldenLayouts.CreateLayout(golden.Config, golden.Seed);
            GameObject level = LevelGeometryGenerator.FromParameters(layout, parameters).GenerateLevel();

            try
            {
                ulong layoutHash = HandBuiltGoldenLayouts.Fnv(HandBuiltGoldenLayouts.Fingerprint(layout, parameters));
                Assert.That(layoutHash, Is.EqualTo(golden.Layout), $"{golden}: layout changed (actual 0x{layoutHash:X16}UL)");

                GeometrySignature geometry = GeometrySignature.FromTriangles(GetTriangles(level));
                Assert.That(golden.Geometry.Matches(geometry, out string difference), Is.True,
                    $"{golden}: geometry changed ({difference}); actual {geometry.ToCode()}");
            }
            finally
            {
                Object.DestroyImmediate(level);
            }
        }

        private static IEnumerable<(Vector3, Vector3, Vector3)> GetTriangles(GameObject level)
        {
            foreach (MeshFilter filter in level.GetComponentsInChildren<MeshFilter>())
            {
                Vector3[] vertices = filter.sharedMesh.vertices;
                int[] triangles = filter.sharedMesh.triangles;

                for (int i = 0; i < triangles.Length; i += 3)
                    yield return (vertices[triangles[i]], vertices[triangles[i + 1]], vertices[triangles[i + 2]]);
            }
        }
    }
